// Function to dynamically retrieve experiences for any city
function generateExperiencesForCity(cityName, stateName = "India") {
    if (!cityName) return CITY_EXPERIENCES["Goa"];
    const cleanCity = cityName.trim();
    if (CITY_EXPERIENCES[cleanCity]) {
        return CITY_EXPERIENCES[cleanCity];
    }
    const lower = cleanCity.toLowerCase();
    for (const k in CITY_EXPERIENCES) {
        if (k.toLowerCase() === lower || lower.includes(k.toLowerCase()) || k.toLowerCase().includes(lower)) {
            return CITY_EXPERIENCES[k];
        }
    }
    return CITY_EXPERIENCES["Goa"] || { party: [], accommodations: [] };
}

// Unified experiences getter
function getUnifiedCityExperiences(cityName, maxBudget = Infinity, activeCategory = 'all', staySubType = 'all') {
    let places = [];
    if (typeof PLACES_DATA !== 'undefined') {
        if (!cityName || cityName.toLowerCase() === 'all') {
            places = PLACES_DATA;
        } else {
            const cLower = cityName.toLowerCase();
            places = PLACES_DATA.filter(p => {
                const pCity = p.city.toLowerCase();
                return pCity === cLower || pCity.includes(cLower) || cLower.includes(pCity);
            });
        }
    }

    let partySpots = [];
    let staySpots = [];

    if (!cityName || cityName.toLowerCase() === 'all') {
        Object.keys(CITY_EXPERIENCES).forEach(c => {
            partySpots.push(...(CITY_EXPERIENCES[c].party || []));
            staySpots.push(...(CITY_EXPERIENCES[c].accommodations || []));
        });
    } else {
        const exp = generateExperiencesForCity(cityName);
        partySpots = exp.party || [];
        staySpots = exp.accommodations || [];
    }

    const filteredPlaces = places.filter(p => (p.fee_raw || 0) <= maxBudget);
    const filteredParty = partySpots.filter(pt => (pt.cost_raw || 0) <= maxBudget);
    const filteredStays = staySpots.filter(st => {
        const matchesBudget = (st.price_raw || 0) <= maxBudget;
        const matchesSubType = (staySubType === 'all' || st.sub_type === staySubType);
        return matchesBudget && matchesSubType;
    });

    return {
        places: filteredPlaces,
        party: filteredParty,
        stays: filteredStays
    };
}
